
%BPM_nanojet_cylinder.m
%Photonic nanojet generated by a dielectric microcylinder, 2D (x,z) BPM
%Project part 2 (Extension: design and simulation of your own device)
%Paramters used for simulation :
%Ld (light wavelength) =1.03, D (cylinder diameter) =10.3, w0 (waist)=39.8,
%np (cylinder index) =1.450 (fused silica), nbg (background) =1.326 (water),
%dz(sample distance along z)=0.025, Z(total distance) =60, all lengths in micrometers
clear
%Gaussian Beam
    N=4096; %N : sampling number
    L=160*10^-6; %Display area (about 4 times the beam width)
    %Ld=input('wavelength of light in [micrometers] = ');
    Ld=1.03;Ld=Ld*10^-6;
    k0=(2*pi)/Ld;  %wavenumber in vacuum, used for the index step
    %w0=input('Waist of Gaussian Beam in [micrometers] = ');
    w0=39.8;w0=w0*10^-6;  %waist of the beam focused in part 1
    %Zw=input('position of the beam waist in [micrometers] = ');
    Zw=10.15;Zw=Zw*10^-6;  %waist at the cylinder centre (flat wavefront)
    %dz=input('step size of z (dz) in [micrometers] = ');
    dz=0.025;dz=dz*10^-6;
    %Z=input('destination of z in [micrometers] = ');
    Z=60;Z=Z*10^-6;
%Microcylinder
    %D=input('Diameter of the cylinder in [micrometers] = ');
    D=10.3;D=D*10^-6;R=D/2;
    zc=5*10^-6+R;  %centre of the cylinder (front face at z=5 um)
    np=1.450;   %fused silica at 1.03 um (Malitson 1965)
    nbg=1.326;  %water at 1.03 um (Hale and Querry 1973)
    kbg=k0*nbg; %reference wavenumber of the BPM (n0=nbg)
    m_rel=np/nbg  %relative index
%dx : step size
    dx=L/N;
    for m=1:N
     %Space axis
        x(m)=(m-1)*dx-L/2;
     %Frequency axis
        Kx(m)=(2*pi*(m-1))/(N*dx)-((2*pi*N)/(N*dx))/2;
    end

%Gaussian Beam at its waist (flat wavefront, on-axis intensity I0=1)
Gau_w=exp(-x.^2./(w0^2));

%Gaussian Beam in space domain at z=0 (waist moved back to z=Zw)
Gau_ini=ifft(fft(Gau_w).*fftshift(exp(j/(2*kbg)*(-Zw)*Kx.^2)));

%Energy of the initial Gaussian beam (per unit length along y)
Energy_ini=dx*sum(abs(Gau_ini).^2)

%Free space transfer function of propagation (in the background medium)
H=exp(j/(2*kbg)*dz*Kx.^2);

%Absorbing boundary (graded, defined per unit length, starts at 80% of the half window)
    alpha=5*10^5;  %absorption coefficient at the window edge [1/m]
    xa=0.8*L/2;
Abs=exp(-alpha*dz*(max(abs(x)-xa,0)/(L/2-xa)).^2);

%Stored region for the plots (|x| < 25 um)
ix=find(abs(x)<=25*10^-6);

%Iterative Loop
Gau=Gau_ini;
n1=0;
Energy_abs=0;
for z=0:dz:Z-dz
    n1=n1+1 ;
    Zp(n1)=z+dz;
    %Gaussian Beam in Frequency domain
      FGau=fft(Gau);
    %Propagated Gaussian beam in Frequency domain
      FGau=FGau.*fftshift(H);
    %Propagated Gaussian beam in space domain
      Gau=ifft(FGau);
    %Refractive index map of the slice z+dz/2 (cylinder of radius R)
      dn=(np-nbg)*((x.^2+(z+dz/2-zc)^2)<=R^2);
    %Step propagation through medium
      Gau=Gau.*exp(-j*k0*dn*dz);
    %Absorbing boundary
      E_before=dx*sum(abs(Gau).^2);
      Gau=Gau.*Abs;
      Energy_abs=Energy_abs+E_before-dx*sum(abs(Gau).^2);
    %Stored intensity and index
      I_pro(:,n1)=abs(Gau(ix)').^2;
      n_pro(:,n1)=nbg+dn(ix)';
end

%Energy of the final propagated beam, to check conservation of energy
Energy_pro=dx*sum(abs(Gau).^2)
Energy_abs
Energy_error=abs(Energy_pro+Energy_abs-Energy_ini)/Energy_ini

%Figures of merit of the nanojet (Darafsheh 2021, fig. 4)
xs=x(ix);
ic=find(xs==0);
zs=zc+R;  %shadow-side surface
I_axis=I_pro(ic,:);
after=find(Zp>zs);
[Imax,k]=max(I_axis(after));
kmax=after(k);
Enhancement=Imax  %I0=1
d_jet_um=(Zp(kmax)-zs)*10^6  %distance of the maximum from the surface
d_geo_um=R*(2-m_rel)/(2*(m_rel-1))*10^6  %ray optics back focal length
%FWHM of the jet at its maximum
P=I_pro(:,kmax)';
iL=find(P(1:ic)<Imax/2,1,'last');
iR=ic-1+find(P(ic:end)<Imax/2,1,'first');
xL=interp1(P(iL:iL+1),xs(iL:iL+1),Imax/2);
xR=interp1(P(iR-1:iR),xs(iR-1:iR),Imax/2);
FWHM_um=(xR-xL)*10^6
FWHM_over_lambda=(xR-xL)/(Ld/nbg)
%Length of the jet (on-axis intensity above Imax/2, behind the surface)
k1=kmax;while k1>after(1) && I_axis(k1-1)>=Imax/2, k1=k1-1; end
k2=kmax;while k2<length(Zp) && I_axis(k2+1)>=Imax/2, k2=k2+1; end
L_half_um=(Zp(k2)-Zp(k1))*10^6

%axis in micrometer scale
xs=xs*10^6;
Zp=Zp*10^6;
th=linspace(0,2*pi,200);

figure(1)
imagesc(Zp,xs,n_pro)
axis xy
axis image  %same scale on z and x
colorbar
title('Refractive index map n(x,z)')
xlabel('z [\mum]')
ylabel('x [\mum]')

figure(2)
imagesc(Zp,xs,I_pro)
axis xy
axis image  %same scale on z and x
colorbar
hold on
plot((zc+R*cos(th))*10^6,R*sin(th)*10^6,'w')
hold off
axis([min(Zp) max(Zp) -15 15])
title('Intensity |E(x,z)|^2 / I_0')
xlabel('z [\mum]')
ylabel('x [\mum]')

figure(3)
plot(Zp,I_axis,'b')
hold on
plot([zs zs]*10^6,[0 1.1*Imax],'k--')
plot([zs zs]*10^6+d_geo_um,[0 1.1*Imax],'r--')
plot(Zp(kmax),Imax,'ro')
hold off
grid on
legend('BPM on axis','shadow surface','ray optics focus','jet maximum')
title('On-axis intensity')
xlabel('z [\mum]')
ylabel('I(0,z) / I_0')

figure(4)
plot(xs,I_pro(:,kmax),'b')
hold on
plot([xL xR]*10^6,[Imax/2 Imax/2],'r-o')
hold off
axis([-10 10 0 1.1*Imax])
grid on
title('Transverse profile at the jet maximum')
xlabel('x [\mum]')
ylabel('I(x,z_{max}) / I_0')
 
%Transverse cross-sections at several z (task 6)  
%just behind the surface, fringe region, jet maximum, after the jet  
zcut=[zs*10^6+0.5 zs*10^6+4 Zp(kmax) zs*10^6+30];  
cut_names={'just behind the surface','fringe region','jet maximum','after the jet'};  
for q=1:4  
    kk(q)=find(abs(Zp-zcut(q))==min(abs(Zp-zcut(q))),1);  
end  
figure(2)  
hold on  
for q=1:4  
    plot([Zp(kk(q)) Zp(kk(q))],[-15 15],'w--')  
end  
hold off  
 
figure(5)  
for q=1:4  
    subplot(2,2,q)  
    plot(xs,I_pro(:,kk(q)),'b')  
    hold on  
    plot([-R R]*10^6,[1 1],'k:')  %incident level I0 over the cylinder width  
    hold off  
    axis([-10 10 0 1.1*max(I_pro(:,kk(q)))])  
    grid on  
    title(sprintf('%s : z - z_s = %.1f \\mum',cut_names{q},Zp(kk(q))-zs*10^6))  
    xlabel('x [\mum]')  
    ylabel('I(x,z) / I_0')  
end  
 
%Figures of merit of the nanojet  
fprintf('\n---------------- Figures of merit ----------------\n');  
fprintf('relative index m           %8.4f\n',m_rel);  
fprintf('jet position d             %8.2f um   (ray optics %5.2f um)\n',d_jet_um,d_geo_um);  
fprintf('enhancement Imax/I0        %8.2f\n',Enhancement);  
fprintf('FWHM                       %8.3f um = %4.2f lambda/n\n',FWHM_um,FWHM_over_lambda);  
fprintf('length L1/2                %8.2f um = %4.1f lambda/n\n',L_half_um,L_half_um/(Ld/nbg*10^6));  
fprintf('energy absorbed            %8.3f %%\n',100*Energy_abs/Energy_ini);  
fprintf('--------------------------------------------------\n');  
